    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '121: In fetal heart rate monitoring, what defines "Baseline Variability"?', '["The average heart rate", "Fluctuations in the baseline heart rate that are irregular in amplitude and frequency", "Accelerations", "Decelerations"]', 1, 'Variability is a reflection of an intact and oxygenated CNS. (ACOG)'),
    (v_topic_id, '122: "Moderate Variability" is defined as a range of:', '["0-2 bpm", "3-5 bpm", "6-25 bpm", "> 25 bpm"]', 2, 'Moderate variability is reassuring. (ACOG)'),
    (v_topic_id, '123: Which type of fetal heart rate deceleration is considered a normal response to head compression during a contraction?', '["Early deceleration", "Variable deceleration", "Late deceleration", "Prolonged deceleration"]', 0, 'Early decels mirror the contraction and are not concerning. (Williams)'),
    (v_topic_id, '124: "Late Decelerations" are associated with which physiological process?', '["Head compression", "Umbilical cord compression", "Uteroplacental insufficiency", "Fetal sleep"]', 2, 'Late decels start after the peak of the contraction and indicate fetal hypoxia. (Beckmann)'),
    (v_topic_id, '125: "Variable Decelerations" are typically caused by:', '["Head compression", "Umbilical cord compression", "Placental abruption", "Maternal fever"]', 1, 'Abrupt drop and return, often "V" or "W" shaped. (ACOG)'),
    (v_topic_id, '126: A "Category I" fetal heart rate tracing is:', '["Abnormal", "Reassuring (Normal)", "Equivocal", "Indicative of acidosis"]', 1, 'Category I includes normal baseline, moderate variability, and no late/variable decels. (ACOG)'),
    (v_topic_id, '127: A "Sinusoidal" fetal heart rate pattern is a Category III tracing often associated with:', '["Fetal sleep", "Severe fetal anemia or hypoxia", "Maternal drug use", "Normal labor"]', 1, 'Smooth, sine-wave like pattern; very concerning. (Williams)'),
    (v_topic_id, '128: What is the first-line management for "Variable Decelerations" in labor?', '["Immediate C-section", "Maternal position change and amnioinfusion", "Oxytocin increase", "Forceps"]', 1, 'Repositioning helps relieve cord compression. (ACOG)'),
    (v_topic_id, '129: "Scalp Stimulation" is performed during labor to:', '["Make the baby cry", "Evoke an acceleration to confirm absence of acidosis", "Monitor temperature", "Check for hair"]', 1, 'An acceleration after stimulation is highly predictive of a normal fetal pH. (Williams)'),
    (v_topic_id, '130: The "Third Stage of Labor" ends with the delivery of the:', '["Baby", "Placenta", "Fetal membranes", "Umbilical cord"]', 1, 'Stage 3 is the placental stage. (Beckmann)'),
    (v_topic_id, '131: What is the primary medication used to prevent Postpartum Hemorrhage (PPH) by inducing uterine contraction?', '["Aspirin", "Oxytocin (Pitocin)", "Labetalol", "Magnesium"]', 1, 'Oxytocin is the first-line uterotonic. (ACOG)'),
    (v_topic_id, '132: Signs of placental separation include a gush of blood, lengthening of the umbilical cord, and:', '["The uterus becoming soft", "The uterus becoming firm and rising in the abdomen", "Maternal shivering", "Fetal heart rate drop"]', 1, 'The uterus changes from discoid to globular shape. (Williams)'),
    (v_topic_id, '133: "Active Management" of the third stage of labor reduces the risk of PPH. It includes oxytocin, controlled cord traction, and:', '["Uterine massage", "Manual removal of the placenta", "Warm blankets", "Bed rest"]', 0, 'Standard of care in many settings. (ACOG)'),
    (v_topic_id, '134: What is the most common cause of Postpartum Hemorrhage?', '["Lacerations", "Retained placenta", "Uterine Atony", "Coagulopathy"]', 2, 'Atony (soft, boggy uterus) accounts for 70-80% of PPH. (Beckmann)'),
    (v_topic_id, '135: "Uterine Atony" risk factors include:', '["Overdistended uterus (twins, polyhydramnios)", "Prolonged labor", "High parity", "All of the above"]', 3, 'Anything that "tires" or overstretches the muscle. (Williams)'),
    (v_topic_id, '136: A patient with PPH has a firm uterus, but continues to bleed. What is the next most likely cause?', '["Atony", "Genital tract lacerations", "Placenta accreta", "Infection"]', 1, 'Firm uterus + bleeding = check for tears. (ACOG)'),
    (v_topic_id, '137: Which uterotonic medication is CONTRAINDICATED in a patient with Hypertension?', '["Oxytocin", "Methylergonovine (Methergine)", "Misoprostol", "Carboprost (Hemabate)"]', 1, 'Ergot alkaloids can cause severe HTN and stroke. (Williams)'),
    (v_topic_id, '138: Which uterotonic medication is CONTRAINDICATED in a patient with Asthma?', '["Oxytocin", "Methergine", "Carboprost (Hemabate/PGF2-alpha)", "Misoprostol"]', 2, 'Prostaglandins can cause bronchoconstriction. (Beckmann)'),
    (v_topic_id, '139: "Uterine Inversion" is a rare obstetric emergency often caused by:', '["Excessive cord traction on an unseparated placenta", "C-section", "Oxytocin use", "Bed rest"]', 0, 'The uterus turns inside out. (Williams)'),
    (v_topic_id, '140: The "Puerperium" (Postpartum period) is traditionally defined as the period lasting how long after delivery?', '["1 week", "2 weeks", "6 weeks", "1 year"]', 2, 'The time it takes for most physiological changes to return to baseline. (Beckmann)'),
    (v_topic_id, '141: "Lochia Rubra" is the normal vaginal discharge after delivery. How long does it typically last?', '["1-2 days", "3-4 days", "2 weeks", "6 weeks"]', 1, 'Red discharge (blood/tissue) for the first few days, followed by serosa and alba. (Williams)'),
    (v_topic_id, '142: Postpartum shivering (chills) immediately after delivery is:', '["A sign of infection", "A sign of hemorrhage", "A normal physiological response", "A drug reaction"]', 2, 'Common and benign; due to hormonal shifts and thermal changes. (Beckmann)'),
    (v_topic_id, '143: When does ovulation typically resume in a NON-lactating woman postpartum?', '["6-10 weeks", "1 year", "Immediately", "Never"]', 0, 'Ovulation can occur as early as 4-5 weeks. (Williams)'),
    (v_topic_id, '144: "Lactational Amenorrhea" is an effective form of contraception ONLY if the mother is:', '["Exclusively breastfeeding", "Amenorrheic", "Less than 6 months postpartum", "All of the above"]', 3, 'The "Rule of Three" for LAM. (ACOG)'),
    (v_topic_id, '145: Which hormone is responsible for "Milk Production" (Synthesis)?', '["Oxytocin", "Prolactin", "Estrogen", "Progesterone"]', 1, 'Prolactin (Anterior Pituitary) makes the milk. (Beckmann)'),
    (v_topic_id, '146: Which hormone is responsible for the "Milk Ejection Reflex" (Let-down)?', '["Prolactin", "Oxytocin", "Cortisol", "Thyroxine"]', 1, 'Oxytocin (Posterior Pituitary) causes myoepithelial contraction. (Williams)'),
    (v_topic_id, '147: "Colostrum" is the first milk produced. It is particularly rich in:', '["Fat", "IgA antibodies", "Sugar", "Water"]', 1, 'Provides critical passive immunity to the newborn. (Beckmann)'),
    (v_topic_id, '148: A breastfeeding mother has a painful, red, swollen area on one breast and a fever of 102F. Diagnosis?', '["Engorgement", "Mastitis", "Breast cancer", "Clogged duct"]', 1, 'Infection of the breast tissue, usually S. aureus. (ACOG)'),
    (v_topic_id, '149: Treatment for Mastitis?', '["Stop breastfeeding", "Antibiotics (e.g., Dicloxacillin) and CONTINUE breastfeeding", "Surgery", "Cold compresses only"]', 1, 'Emptying the breast is vital for resolution. (Williams)'),
    (v_topic_id, '150: A "Breast Abscess" differs from mastitis by the presence of:', '["Fever", "Fluctuance/pitting on palpation", "Redness", "Pain"]', 1, 'Abscess requires drainage. (Beckmann)'),
    (v_topic_id, '151: "Postpartum Blues" typically peaks around day 5 and resolves by:', '["Day 10-14", "Month 6", "1 week", "It never resolves"]', 0, 'Benign and very common (up to 80% of women). (ACOG)'),
    (v_topic_id, '152: "Postpartum Depression" is distinguished from blues by its duration (> 2 weeks) and:', '["Presence of psychosis", "Interference with daily functioning and bonding", "Fever", "Weight gain"]', 1, 'Requires professional treatment (therapy/SSRI). (Beckmann)'),
    (v_topic_id, '153: Postpartum Psychosis is a medical emergency because of the risk of:', '["Infection", "Infanticide or Suicide", "Hemorrhage", "Diabetes"]', 1, 'Requires immediate hospitalization. (Williams)'),
    (v_topic_id, '154: A 1-minute APGAR score of 3 indicates:', '["A healthy baby", "A baby requiring immediate resuscitation", "A baby with a genetic defect", "A normal finding"]', 1, 'Scores 0-3 are critically low. (Beckmann)'),
    (v_topic_id, '155: What are the five components of the APGAR score?', '["HR, Respiratory effort, Muscle tone, Reflex irritability, Color", "Weight, Length, HR, Color, Reflex", "HR, Temp, Tone, Crying, Sucking", "None of the above"]', 0, 'Appearance, Pulse, Grimace, Activity, Respiration. (Williams)'),
    (v_topic_id, '156: Routine newborn care includes Vitamin K injection to prevent:', '["Infection", "Vitamin K Deficiency Bleeding (VKDB)", "Jaundice", "Rickets"]', 1, 'Newborns are born with low vitamin K. (AAP/ACOG)'),
    (v_topic_id, '157: Erythromycin ophthalmic ointment is given to newborns to prevent:', '["Blindness from Chlamydial conjunctivitis", "Gonococcal ophthalmia neonatorum", "Cataracts", "Glaucoma"]', 1, 'Universal prophylaxis for gonorrhea. (Beckmann)'),
    (v_topic_id, '158: "Physiologic Jaundice" in the newborn typically peaks at day 3-5 and is due to:', '["Liver failure", "Hemolysis and immature liver conjugation", "Biliary atresia", "Breast milk allergy"]', 1, 'Normal adaptation; unconjugated bilirubin increases. (Williams)'),
    (v_topic_id, '159: "Caput Succedaneum" is a scalp swelling that:', '["Crosses suture lines", "Is limited by suture lines", "Requires surgery", "Contains blood only"]', 0, 'Benign edema; resolves in days. (Beckmann)'),
    (v_topic_id, '160: A "Cephalohematoma" is a subperiosteal hemorrhage that:', '["Crosses suture lines", "Is limited by suture lines", "Is always present at birth", "Causes skull fractures"]', 1, 'Does NOT cross sutures; may take weeks to resolve. (Williams)'),
    (v_topic_id, '161: Which medication used for PPH is a prostaglandin E1 analog that can be given rectally or sublingually?', '["Oxytocin", "Methylergonovine", "Misoprostol (Cytotec)", "Hemabate"]', 2, 'Commonly used in atony. (ACOG)'),
    (v_topic_id, '162: "Endometritis" is the most common cause of postpartum fever. It is most frequently seen after:', '["Vaginal delivery", "Cesarean section (especially after labor/ROM)", "Forceps delivery", "Water birth"]', 1, 'C-section is the #1 risk factor. (Williams)'),
    (v_topic_id, '163: Standard treatment for Post-C-section Endometritis?', '["Oral Amoxicillin", "IV Clindamycin and Gentamicin", "Vancomycin only", "Hysterectomy"]', 1, 'Provides broad coverage including anaerobes. (ACOG)'),
    (v_topic_id, '164: Septic Pelvic Thrombophlebitis is suspected when postpartum fever:', '["Is very high", "Persists despite broad-spectrum antibiotics", "Occurs on day 1", "Is associated with a rash"]', 1, 'Diagnosis of exclusion; treated with Heparin + Antibiotics. (Williams)'),
    (v_topic_id, '165: "Sheehan Syndrome" is postpartum pituitary necrosis caused by:', '["Infection", "Severe obstetric hemorrhage and hypotension", "Diabetes", "Pituitary tumor"]', 1, 'Leads to failure to lactate and loss of other pituitary functions. (Beckmann)'),
    (v_topic_id, '166: A breastfeeding mother should increase her daily caloric intake by approximately how much?', '["100 kcal", "500 kcal", "1000 kcal", "No increase needed"]', 1, 'Lactation is energetically expensive. (IOM)'),
    (v_topic_id, '167: Contraindications to breastfeeding include:', '["Maternal HIV (in developed countries)", "Active, untreated TB", "Use of certain drugs (e.g., lithium, chemotherapy)", "All of the above"]', 3, 'Also includes Galactosemia in the infant. (AAP/ACOG)'),
    (v_topic_id, '168: "Engorgement" of the breasts occurs day 3-5 postpartum and is best managed by:', '["Stopping breastfeeding", "Frequent feeding/pumping and cool compresses", "Antibiotics", "Binder"]', 1, 'Due to increased blood/lymph and milk. (Beckmann)'),
    (v_topic_id, '169: What is the primary benefit of the "Skin-to-Skin" (Kangaroo care) contact immediately after birth?', '["Fetal growth", "Thermoregulation and bonding", "Prevents infection", "Increases APGAR score"]', 1, 'Standard of care for stable infants. (AAP)'),
    (v_topic_id, '170: Postpartum "Diuresis" (increased urination) occurs in the first week because:', '["The mother drinks too much", "Excretion of excess extracellular fluid accumulated during pregnancy", "Kidney failure", "Diabetes"]', 1, 'Normal physiological return to baseline. (Williams)'),
    (v_topic_id, '171: At 1 week postpartum, the uterus should be palpable at the level of:', '["The umbilicus", "Midway between umbilicus and symphysis", "The xiphoid", "It should not be palpable"]', 1, 'The uterus involutes rapidly. (Beckmann)'),
    (v_topic_id, '172: When is the "Postpartum Check-up" typically scheduled for a low-risk patient?', '["1 week", "2 weeks", "6 weeks", "6 months"]', 2, 'Traditional timing for final assessment. (ACOG)'),
    (v_topic_id, '173: Which of the following is a symptom of a "Dural Puncture Headache" (Spinal headache) after an epidural?', '["Pain that is better when lying flat and worse when upright", "Constant throbbing", "Pain behind the eyes", "Better when walking"]', 0, 'Positional headache is characteristic. (Williams)'),
    (v_topic_id, '174: Treatment for a severe spinal headache?', '["Hydration", "Caffeine", "Epidural Blood Patch", "Antibiotics"]', 2, 'Injecting maternal blood to "seal" the puncture. (Beckmann)'),
    (v_topic_id, '175: Maternal "Thyroiditis" is a common postpartum autoimmune condition. Its initial phase is usually:', '["Hypothyroid", "Hyperthyroid", "Euthyroid", "A goiter only"]', 1, 'Followed by a hypothyroid phase. (Williams)'),
    (v_topic_id, '176: What percentage of women experience some form of "Postpartum Blues"?', '["10%", "25%", "Up to 80%", "None"]', 2, 'Extremely common and usually transient. (ACOG)'),
    (v_topic_id, '177: Which contraception method is typically avoided for the first 3-6 weeks postpartum due to VTE risk?', '["Progestin-only pill", "IUD", "Combined Hormonal Contraceptives (Pill/Patch/Ring)", "Condoms"]', 2, 'Estrogen increases clotting risk in the early postpartum period. (CDC MEC)'),
    (v_topic_id, '178: "Meconium" is:', '["The first newborn stool (dark green/black)", "A type of amniotic fluid", "An infection", "A lung condition"]', 0, 'Normal newborn finding; passage in utero can be a sign of stress. (Beckmann)'),
    (v_topic_id, '179: A newborn with "nasal flaring" and "intercostal retractions" has:', '["Normal breathing", "Respiratory distress", "Hunger", "Cold"]', 1, 'Signs of increased work of breathing. (Williams)'),
    (v_topic_id, '180: The "Umbilical Cord" typically falls off within:', '["24 hours", "1-3 weeks", "1 month", "Never"]', 1, 'Keep clean and dry until it separates. (Beckmann)');
